from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta


class SpyLongCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        equity = self.AddEquity(
            "SPY",
            Resolution.Minute,
            data_normalization_mode=DataNormalizationMode.Raw
        )
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )
        self.option_symbol = option.Symbol

        self.closes = deque(maxlen=20)

        self._bucket_key = None
        self._bucket_bars = {}

        self.entry_ticket = None
        self.entry_symbol = None
        self.entry_fill_price = None
        self.entry_expiry = None

        self.exit_ticket = None
        self.no_entry_date = None
        self.equity_liquidation_ticket = None
        self.current_slice = None

    def OnData(self, slice: Slice):
        self.current_slice = slice
        today = self.Time.date()

        self._handle_unexpected_equity_position()
        self._handle_expiration()
        self._evaluate_option_exit()

        if self.spy in slice.Bars:
            self._update_five_minute_bar(slice.Bars[self.spy])

    def _update_five_minute_bar(self, minute_bar: TradeBar):
        end_time = minute_bar.EndTime.replace(second=0, microsecond=0)
        date = end_time.date()
        minute = end_time.hour * 60 + end_time.minute

        # Minute bars are identified by their end time. The first regular
        # session five-minute bar ends at 09:35.
        first_minute_end = 9 * 60 + 31
        session_end = 16 * 60

        if minute < first_minute_end or minute > session_end:
            return

        bucket_end_minute = 9 * 60 + 35 + ((minute - first_minute_end) // 5) * 5
        bucket_end = datetime(
            date.year,
            date.month,
            date.day,
            bucket_end_minute // 60,
            bucket_end_minute % 60
        )

        key = (date, bucket_end)

        if self._bucket_key is not None and key != self._bucket_key:
            self._finalize_five_minute_bucket()

        if self._bucket_key != key:
            self._bucket_key = key
            self._bucket_bars = {}

        self._bucket_bars[end_time] = minute_bar

        if len(self._bucket_bars) == 5:
            self._finalize_five_minute_bucket()

    def _finalize_five_minute_bucket(self):
        if self._bucket_key is None:
            return

        bars = self._bucket_bars
        key = self._bucket_key

        # Do not synthesize an incomplete five-minute bar.
        if len(bars) != 5:
            self._bucket_key = None
            self._bucket_bars = {}
            return

        expected_minutes = sorted(bars.keys())
        if any(
            expected_minutes[i] - expected_minutes[i - 1] != timedelta(minutes=1)
            for i in range(1, len(expected_minutes))
        ):
            self._bucket_key = None
            self._bucket_bars = {}
            return

        close = bars[expected_minutes[-1]].Close
        bar_end = key[1]

        self._bucket_key = None
        self._bucket_bars = {}

        self._on_five_minute_close(close, bar_end)

    def _on_five_minute_close(self, close: float, bar_end: datetime):
        previous_fast = None
        previous_slow = None

        if len(self.closes) >= 20:
            previous_fast = sum(list(self.closes)[-5:]) / 5.0
            previous_slow = sum(self.closes) / 20.0

        self.closes.append(float(close))

        if len(self.closes) < 20:
            return

        current_fast = sum(list(self.closes)[-5:]) / 5.0
        current_slow = sum(self.closes) / 20.0

        if previous_fast is None or previous_slow is None:
            return

        bullish_crossover = (
            previous_fast <= previous_slow
            and current_fast > current_slow
        )

        if not bullish_crossover:
            return

        if not (
            (bar_end.hour > 9 or (bar_end.hour == 9 and bar_end.minute >= 45))
            and
            (bar_end.hour < 14 or (bar_end.hour == 14 and bar_end.minute <= 30))
        ):
            return

        self._try_enter()

    def _try_enter(self):
        today = self.Time.date()

        if self.no_entry_date == today:
            return

        if self._has_option_position() or self._entry_order_open():
            return

        if self.Portfolio[self.spy].Invested:
            return

        if self.current_slice is None or not self.current_slice.OptionChains:
            self.Debug("Skipped entry: no option chain.")
            return

        if self.spy not in self.current_slice.Bars:
            self.Debug("Skipped entry: no current SPY price.")
            return

        spy_price = float(self.current_slice.Bars[self.spy].Close)
        minimum_expiry = today + timedelta(days=7)

        contracts = []
        for chain in self.current_slice.OptionChains.Values:
            for contract in chain.Contracts.Values:
                expiry_date = contract.Expiry.date()

                if (
                    contract.Right == OptionRight.Call
                    and expiry_date >= minimum_expiry
                ):
                    contracts.append(contract)

        if not contracts:
            self.Debug("Skipped entry: no qualifying call expiration.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in contracts)
        strike_floor = 1.01 * spy_price

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == nearest_expiry
            and contract.Strike >= strike_floor
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        selected = min(
            candidates,
            key=lambda contract: (
                float(contract.Strike),
                str(contract.Symbol)
            )
        )

        self.entry_symbol = selected.Symbol
        self.entry_expiry = selected.Expiry.date()
        self.entry_fill_price = None

        self.entry_ticket = self.MarketOrder(
            self.entry_symbol,
            1,
            tag="SPY bullish five-minute crossover"
        )

        self.Debug(
            f"Entry submitted: {self.entry_symbol}, "
            f"expiry={self.entry_expiry}, strike={selected.Strike}"
        )

    def _evaluate_option_exit(self):
        if not self._has_option_position():
            return

        if self.entry_symbol is None or self.entry_fill_price is None:
            return

        if self._exit_order_open():
            return

        bid, ask = self._current_option_quote(self.entry_symbol)

        # Profit target requires strictly positive bid and ask.
        if bid is not None and ask is not None and bid > 0 and ask > 0:
            midpoint = (bid + ask) / 2.0

            if midpoint >= 1.50 * self.entry_fill_price:
                self._submit_exit("50% profit target")
                return

        if self.entry_expiry is None:
            return

        previous_trading_day = self._previous_trading_day(self.entry_expiry)

        if (
            self.Time.date() == previous_trading_day
            and (self.Time.hour > 15 or
                 (self.Time.hour == 15 and self.Time.minute >= 45))
        ):
            self._submit_exit("expiration time stop")

    def _handle_expiration(self):
        if not self._has_option_position() or self.entry_expiry is None:
            return

        if self.Time.date() >= self.entry_expiry:
            self.no_entry_date = self.Time.date()

            if not self._exit_order_open():
                self._submit_exit("expiration protection")

    def _submit_exit(self, reason: str):
        if self.entry_symbol is None:
            return

        quantity = self.Portfolio[self.entry_symbol].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None and self._order_open(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing exit order")

        self.exit_ticket = self.MarketOrder(
            self.entry_symbol,
            -quantity,
            tag=reason
        )

        self.Debug(f"Exit submitted: {self.entry_symbol}, reason={reason}")

    def _handle_unexpected_equity_position(self):
        holding = self.Portfolio[self.spy]

        if holding.Quantity == 0:
            return

        if (
            self.equity_liquidation_ticket is not None
            and self._order_open(self.equity_liquidation_ticket)
        ):
            return

        self.Debug(
            f"Unexpected SPY equity position detected, quantity={holding.Quantity}; "
            "liquidating."
        )

        self.equity_liquidation_ticket = self.MarketOrder(
            self.spy,
            -holding.Quantity,
            tag="Unexpected exercise or assignment liquidation"
        )

    def OnAssignmentOrderEvent(self, assignment_event):
        self.Debug(
            f"Unexpected option assignment/exercise processed: "
            f"{assignment_event}"
        )
        self._handle_unexpected_equity_position()

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.entry_fill_price = float(order_event.FillPrice)
                    self.Debug(
                        f"Entry filled: {self.entry_symbol}, "
                        f"price={self.entry_fill_price:.4f}"
                    )
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.Debug("Entry order did not fill.")
                    self.entry_ticket = None
                    self.entry_symbol = None
                    self.entry_expiry = None
                    self.entry_fill_price = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(f"Exit filled: {order_event.Symbol}")
                    self.exit_ticket = None
                    self.entry_ticket = None
                    self.entry_symbol = None
                    self.entry_expiry = None
                    self.entry_fill_price = None
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.exit_ticket = None

    def _current_option_quote(self, symbol):
        if self.current_slice is None:
            return None, None

        for chain in self.current_slice.OptionChains.Values:
            contract = chain.Contracts.get(symbol)
            if contract is not None:
                return float(contract.BidPrice), float(contract.AskPrice)

        return None, None

    def _has_option_position(self):
        return (
            self.entry_symbol is not None
            and self.Portfolio[self.entry_symbol].Quantity != 0
        )

    def _entry_order_open(self):
        return (
            self.entry_ticket is not None
            and self._order_open(self.entry_ticket)
        )

    def _exit_order_open(self):
        return (
            self.exit_ticket is not None
            and self._order_open(self.exit_ticket)
        )

    @staticmethod
    def _order_open(ticket):
        return ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

    def _previous_trading_day(self, expiry_date):
        day = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(
            datetime(day.year, day.month, day.day)
        ):
            day -= timedelta(days=1)

        return day
