        bucket_end = end.replace(
            hour=bucket_minute // 60,
            minute=bucket_minute % 60,
            second=0,
            microsecond=0
        )

        if self.bucket_end is not None and bucket_end != self.bucket_end:
            self.bucket_bars = {}

        if self.bucket_end != bucket_end:
            self.bucket_end = bucket_end
            self.bucket_bars = {}

        self.bucket_bars[end] = bar

        if end != bucket_end:
            return

        expected = [
            bucket_end - timedelta(minutes=i)
            for i in range(4, -1, -1)
        ]

        if any(timestamp not in self.bucket_bars for timestamp in expected):
            self.Debug(
                f"Skipped incomplete SPY five-minute interval ending "
                f"{bucket_end:%Y-%m-%d %H:%M}"
            )
            self.bucket_bars = {}
