    def _build_five_minute_bar(self, minute_bar):
        start = minute_bar.Time
        hour = start.hour
        minute = start.minute

        if hour < 9 or hour > 15:
            return None

        start_minutes = hour * 60 + minute
        if start_minutes < 570 or start_minutes >= 960:
            return None

        bucket_start_minutes = 570 + ((start_minutes - 570) // 5) * 5
        bucket_hour = bucket_start_minutes // 60
        bucket_minute = bucket_start_minutes % 60
        bucket_key = (start.date(), bucket_start_minutes)

