        self.bucket_end = None
        self.bucket_bars = []

    def OnData(self, slice: Slice):
        self.current_slice = slice
        now = self.Time
        today = now.date()

        self._handle_unexpected_spy_position()
        self._handle_expiration_processing(today)

        if self.held_option is not None:
            self._evaluate_option_exit(slice)

        if self._entry_is_open():
            return

        if self.held_option is not None:
            return

        if self.expiration_block_date == today:
            return

        if self.spy not in slice.Bars:
            return

        self._accept_minute_bar(slice.Bars[self.spy])

    def _accept_minute_bar(self, bar: TradeBar):
        end_time = bar.EndTime
        trade_date = end_time.date()

        if trade_date != self.bucket_date:
            self.bucket_date = trade_date
            self.bucket_end = None
            self.bucket_bars = []

        if end_time.time() < datetime.strptime("09:31", "%H:%M").time():
            return

        if end_time.time() > datetime.strptime("16:00", "%H:%M").time():
            return

        anchor = end_time.replace(hour=9, minute=35, second=0, microsecond=0)
        bucket_number = (end_time - anchor).total_seconds() // 300
        bucket_end = anchor + timedelta(minutes=5 * int(bucket_number))

        if self.bucket_end is None:
            self.bucket_end = bucket_end

        if bucket_end != self.bucket_end:
            self._process_completed_bucket()
            self.bucket_end = bucket_end
            self.bucket_bars = []

        if any(existing.EndTime == end_time for existing in self.bucket_bars):
            return

        self.bucket_bars.append(bar)

        if end_time == self.bucket_end:
            self._process_completed_bucket()
            self.bucket_bars = []

    def _process_completed_bucket(self):
        if self.bucket_end is None or len(self.bucket_bars) != 5:
            return

        expected_times = [
            self.bucket_end - timedelta(minutes=minutes)
            for minutes in (4, 3, 2, 1, 0)
        ]
        actual_times = sorted(bar.EndTime for bar in self.bucket_bars)

        if actual_times != expected_times:
            return

        close = self.bucket_bars[-1].Close
        if close <= 0:
            return

        prior_fast = None
        prior_slow = None

        if len(self.closes) >= self.slow_period:
            prior_fast = sum(list(self.closes)[-self.fast_period:]) / self.fast_period
            prior_slow = sum(self.closes) / self.slow_period

        self.closes.append(close)

        if len(self.closes) < self.slow_period:
            return

        current_fast = sum(list(self.closes)[-self.fast_period:]) / self.fast_period
        current_slow = sum(self.closes) / self.slow_period

        bullish_cross = (
            prior_fast is not None and
            prior_slow is not None and
            prior_fast <= prior_slow and
            current_fast > current_slow
        )

        end_time = self.bucket_end.time()
        eligible_time = (
            datetime.strptime("09:45", "%H:%M").time()
            <= end_time
            <= datetime.strptime("14:30", "%H:%M").time()
        )

        if bullish_cross and eligible_time:
            self._try_enter_call()

    def _try_enter_call(self):
        if self.current_slice is None:
            return

        if self.held_option is not None or self._entry_is_open():
            return

        if self.expiration_block_date == self.Time.date():
            return

        if self.spy not in self.current_slice.Bars:
            self.Debug("Skipped entry: no current SPY price.")
            return

        spy_price = self.current_slice.Bars[self.spy].Close
        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        chain = self.current_slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

        minimum_expiration = self.Time.date() + timedelta(days=7)

        contracts = [
            contract
            for contract in chain.Contracts.Values
            if contract.Symbol.ID.OptionRight == OptionRight.Call
            and contract.Symbol.ID.Date.date() >= minimum_expiration
        ]

        if not contracts:
            self.Debug("Skipped entry: no expiration at least seven days away.")
            return

        expiration = min(
            contract.Symbol.ID.Date.date()
            for contract in contracts
        )

        strike_floor = 1.01 * spy_price
        candidates = [
            contract
            for contract in contracts
            if contract.Symbol.ID.Date.date() == expiration
            and contract.Strike >= strike_floor
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Entry submitted: {selected.Symbol}; "
            f"expiration={expiration}; strike={selected.Strike}"
        )

