                "Unexpected exercise or assignment"
            )
            self.Debug(
                "Unexpected exercise or assignment: liquidating SPY"
            )

    def _submit_exit(self, tag):
        if self.held_contract is None or self.exit_ticket is not None:
            return

        quantity = -self.Portfolio[self.held_contract].Quantity

        if quantity != 0:
            self.exit_ticket = self.MarketOrder(
                self.held_contract,
                quantity,
                tag=tag
            )

    def _entry_order_open(self):
        return (
            self.entry_ticket is not None
            and self.entry_ticket.Status not in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            )
        )

    def _previous_trading_day(self, date):
        previous = date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(previous):
            previous -= timedelta(days=1)

        return previous

    def _clear_position(self):
        self.held_contract = None
        self.entry_price = None
        self.expiration_date = None
        self.time_stop_date = None
