        self._update_averages_and_check_signal(slice, consolidated)

    def _update_averages_and_check_signal(self, slice, bar):
        prior_fast = self.fast.Current.Value if self.fast.IsReady else None
        prior_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not (self.fast.IsReady and self.slow.IsReady):
            return

        if prior_fast is None or prior_slow is None:
            return

        if not (time(9, 45) <= bar.EndTime.time() <= time(14, 30)):
            return

        bullish_cross = (
            prior_fast <= prior_slow and
            self.fast.Current.Value > self.slow.Current.Value
        )

        if not bullish_cross:
            return

        if self.skip_entry_date == self.Time.date():
            return

        if self.held_contract is not None or self._entry_order_open():
            return

        self._attempt_entry(slice)

    def _attempt_entry(self, slice):
        if slice.OptionChains is None or len(slice.OptionChains) == 0:
            self.Debug("Skipped entry: no option chain")
            return

        chains = list(slice.OptionChains.Values)
        contracts = [contract for chain in chains for contract in chain]

        today = self.Time.date()
        eligible = [
            contract for contract in contracts
            if contract.Expiry.date() >= today + timedelta(days=7)
        ]

        if not eligible:
            self.Debug("Skipped entry: no expiration at least 7 days out")
            return

        expiration = min(contract.Expiry.date() for contract in eligible)

        spy_price = self.Securities[self.spy].Price
        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price")
            return

