            ask = quote.Ask.Close

            if bid > 0 and ask > 0:
                midpoint = (bid + ask) / 2

                if midpoint >= 1.5 * self.entry_price:
                    self._submit_exit("50 percent profit target")
                    self.Debug("Exit submitted: profit target")
                    return

        if (
            self.Time.date() == self.time_stop_date
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("expiration time stop")
            self.Debug("Exit submitted: expiration time stop")

    def _handle_expiration_processing(self):
        if self.held_contract is None:
            return

        if (
            self.Time.date() >= self.expiration_date
            and self.Portfolio[self.held_contract].Invested
        ):
            self.skip_entry_date = self.Time.date()

            if self.exit_ticket is None:
                self._submit_exit("expiration processing")
                self.Debug("Exit submitted: expiration processing")

    def _handle_unexpected_equity(self, slice):
        if self.Portfolio[self.spy].Invested:
